#include <bits/stdc++.h>
using namespace std;

double d2(double ax, double ay, double bx, double by) {
    return (bx - ax) * (bx - ax) + (by - ay) * (by - ay);
}

vector<double> crossSimple(long long x, long long y, long long r, long long tx, long long ty, long long tr) {
    double d2Val = d2(x, y, tx, ty);
    double r2 = r * r;
    double tr2 = tr * tr;
    if (d2Val < (r - tr) * (r - tr) || d2Val > (r + tr) * (r + tr))
        return {};
    double base = atan2(ty - y, tx - x);
    double sqrt_d2 = sqrt(d2Val);
    double cos_wing = (d2Val + r2 - tr2) / (2.0 * sqrt_d2 * r);
    // Numerical issues might cause cos_wing to be slightly outside [-1,1]
    if (cos_wing > 1.0) cos_wing = 1.0;
    if (cos_wing < -1.0) cos_wing = -1.0;
    double wing = acos(cos_wing);
    return {base - wing, base + wing};
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<array<long long, 3>> circles(n);
    for (int i = 0; i < n; i++) {
        cin >> circles[i][0] >> circles[i][1] >> circles[i][2];
    }

    vector<vector<double>> candidatePoints;
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            vector<double> angles = crossSimple(circles[i][0], circles[i][1], circles[i][2],
                                                 circles[j][0], circles[j][1], circles[j][2]);
            for (double angle : angles) {
                double x = circles[i][0] + circles[i][2] * cos(angle);
                double y = circles[i][1] + circles[i][2] * sin(angle);
                candidatePoints.push_back({x, y});
            }
        }
    }

    int size = (int)candidatePoints.size();
    vector<bool> toRemove(size, false);
    for (int i = 0; i < size; i++) {
        for (int j = i + 1; j < size; j++) {
            if (d2(candidatePoints[i][0], candidatePoints[i][1], candidatePoints[j][0], candidatePoints[j][1]) < 1e-12) {
                toRemove[j] = true;
            }
        }
    }

    vector<vector<double>> uniquePts;
    for (int i = 0; i < size; i++) {
        if (!toRemove[i]) {
            uniquePts.push_back(candidatePoints[i]);
        }
    }

    int totalPoints = (int)uniquePts.size();
    int totalEdges = 0;
    int components = 1;
    for (int i = 0; i < n; i++) {
        int edgeCount = 0;
        for (auto &p : uniquePts) {
            double dist2 = d2(p[0], p[1], circles[i][0], circles[i][1]);
            if (fabs(dist2 - circles[i][2] * circles[i][2]) < 1e-12) {
                edgeCount++;
            }
        }
        if (edgeCount == 0) components++;
        totalEdges += edgeCount;
    }
    if (components > n) components = n;
    cout << totalEdges - totalPoints + components + 1 << "\n";
    return 0;
}

